ents_url":"https://api.github.com/users/djalmajr/received_events","repos_url":"https://api.github.com/users/djalmajr/repos","site_admin":false,"starred_url":"https://api.github.com/users/djalmajr/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/djalmajr/subscriptions","type":"User","url":"https://api.github.com/users/djalmajr","user_view_type":"public"},"html_url":"https://github.com/djalmajr/frame/commit/f490040448a2e100af96e02aa9ea3d8746fe162d","node_id":"C_kwDOQ78T_NoAKGY0OTAwNDA0NDhhMmUxMDBhZjk2ZTAyYWE5ZWEzZDg3NDZmZTE2MmQ","parents":[{"html_url":"https://github.com/djalmajr/frame/commit/5396f77f08c36389159213bdf3a6710f18b4b2bb","sha":"5396f77f08c36389159213bdf3a6710f18b4b2bb","url":"https://api.github.com/repos/djalmajr/frame/commits/5396f77f08c36389159213bdf3a6710f18b4b2bb"}],"sha":"f490040448a2e100af96e02aa9ea3d8746fe162d","url":"https://api.github.com/repos/djalmajr/frame/commits/f490040448a2e100af96e02aa9ea3d8746fe162d"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/1858147?v=4","events_url":"https://api.github.com/users/djalmajr/events{/privacy}","followers_url":"https://api.github.com/users/djalmajr/followers","following_url":"https://api.github.com/users/djalmajr/following{/other_user}","gists_url":"https://api.github.com/users/djalmajr/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/djalmajr","id":1858147,"login":"djalmajr","node_id":"MDQ6VXNlcjE4NTgxNDc=","organizations_url":"https://api.github.com/users/djalmajr/orgs","received_events_url":"https://api.github.com/users/djalmajr/received_events","repos_url":"https://api.github.com/users/djalmajr/repos","site_admin":false,"starred_url":"https://api.github.com/users/djalmajr/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/djalmajr/subscriptions","type":"User","url":"https://api.github.com/users/djalmajr","user_view_type":"public"},"comments_url":"https://api.github.com/repos/djalmajr/frame/commits/5396f77f08c36389159213bdf3a6710f18b4b2bb/comments","commit":{"author":{"date":"2026-08-26T17:18:25Z","email":"djalmajr@gmail.com","name":"Djalma Júnior"},"comment_count":0,"committer":{"date":"2026-08-26T17:18:25Z","email":"djalmajr@gmail.com","name":"Djalma Júnior"},"message":"feat(frame): allow — Permissions Policy do iframe como atributo de primeira classe\n\nVazio por default (camera/microfone/geolocation ficam opt-in por embed);\naplicado na criação do iframe, recriado na mudança (a policy é computada no\nload do documento — mesma semântica do sandbox), presente nas props do INIT.\n\nJunto, a suíte sai da podridão: o MessagePort do setup era um stub vazio\nsombreando o MessageChannel real do Bun, o sdk.test sombreava o construtor\nMessageEvent com o enum de constants e nenhum INIT levava ports — a cascata\nde timeouts não era o código, era o harness. 175 testes, processo encerra\nsozinho, cobertura nova do allow nos três níveis (frame, sdk, integração).","tree":{"sha":"2c2ae647c29796ba3d4a38e19395c0f09029e13a","url":"https://api.github.com/repos/djalmajr/frame/git/trees/2c2ae647c29796ba3d4a38e19395c0f09029e13a"},"url":"https://api.github.com/repos/djalmajr/frame/git/commits/5396f77f08c36389159213bdf3a6710f18b4b2bb","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/1858147?v=4","events_url":"https://api.github.com/users/djalmajr/events{/privacy}","followers_url":"https://api.github.com/users/djalmajr/followers","following_url":"https://api.github.com/users/djalmajr/following{/other_user}","gists_url":"https://api.github.com/users/djalmajr/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/djalmajr","id":1858147,"login":"djalmajr","node_id":"MDQ6VXNlcjE4NTgxNDc=","organizations_url":"https://api.github.com/users/djalmajr/orgs","received_events_url":"https://api.github.com/users/djalmajr/received_events","repos_url":"https://api.github.com/users/dja