hese changes streamline the FragmentFrame class, enhancing its responsiveness and maintainability.","tree":{"sha":"dc5864599db0abdbf230d0767bfef70250281126","url":"https://api.github.com/repos/andersonmfjr/frame/git/trees/dc5864599db0abdbf230d0767bfef70250281126"},"url":"https://api.github.com/repos/andersonmfjr/frame/git/commits/161ee3b9de16fcd82858379a2dc238cd23736e65","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/1858147?v=4","events_url":"https://api.github.com/users/djalmajr/events{/privacy}","followers_url":"https://api.github.com/users/djalmajr/followers","following_url":"https://api.github.com/users/djalmajr/following{/other_user}","gists_url":"https://api.github.com/users/djalmajr/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/djalmajr","id":1858147,"login":"djalmajr","node_id":"MDQ6VXNlcjE4NTgxNDc=","organizations_url":"https://api.github.com/users/djalmajr/orgs","received_events_url":"https://api.github.com/users/djalmajr/received_events","repos_url":"https://api.github.com/users/djalmajr/repos","site_admin":false,"starred_url":"https://api.github.com/users/djalmajr/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/djalmajr/subscriptions","type":"User","url":"https://api.github.com/users/djalmajr","user_view_type":"public"},"html_url":"https://github.com/andersonmfjr/frame/commit/161ee3b9de16fcd82858379a2dc238cd23736e65","node_id":"C_kwDOQ8L6Y9oAKDE2MWVlM2I5ZGUxNmZjZDgyODU4Mzc5YTJkYzIzOGNkMjM3MzZlNjU","parents":[{"html_url":"https://github.com/andersonmfjr/frame/commit/5aabf9ce38b85634722f66bc716fd0ffd682d1d8","sha":"5aabf9ce38b85634722f66bc716fd0ffd682d1d8","url":"https://api.github.com/repos/andersonmfjr/frame/commits/5aabf9ce38b85634722f66bc716fd0ffd682d1d8"}],"sha":"161ee3b9de16fcd82858379a2dc238cd23736e65","url":"https://api.github.com/repos/andersonmfjr/frame/commits/161ee3b9de16fcd8